 lessons:[
  {title:'¿Qué es la seguridad vial?', simple:'Son las decisiones, reglas y acciones que ayudan a evitar accidentes y proteger a las personas en la carretera.', detail:['No se trata solo de manejar un carro: incluye a peatones, ciclistas, motociclistas y pasajeros.','La seguridad es una responsabilidad compartida: cada persona puede prevenir riesgos.'], example:'Cuando una conductora reduce la velocidad cerca de una escuela, protege a quienes cruzan, aunque nadie se lo haya pedido.', remember:'La seguridad vial empieza antes de encender el motor.'},
  {title:'¿Para qué sirve?', simple:'Sirve para prevenir accidentes, disminuir lesiones y cuidar la vida.', detail:['Prevenir: evitar que ocurra un hecho peligroso.','Reducir el daño: usar medidas de protección y conducir con atención.','Promover respeto: compartir la vía sin poner a otros en peligro.'], example:'Usar el cinturón no evita que ocurra todo choque, pero puede disminuir sus consecuencias.', remember:'Prevenir es mejor que reaccionar tarde.'},
  {title:'Los 5 principios fáciles', simple:'Recordá estas palabras: legalidad, respeto, prevención, responsabilidad y solidaridad.', detail:['Legalidad: cumplir las normas. Respeto: reconocer a todos los usuarios de la vía.','Prevención: anticipar riesgos. Responsabilidad: responder por tus decisiones.','Solidaridad: ayudar y proteger a otras personas en el tránsito.'], example:'Ceder el paso a una persona que cruza correctamente demuestra respeto y prevención.', remember:'L-R-P-R-S: legalidad, respeto, prevención, responsabilidad y solidaridad.'}
 ],
