const PAGE_GUIDES=[["seguridad", "resumen-04", "Objetivos y principios de seguridad vial", "Seguridad vial significa reducir los accidentes y proteger a todas las personas que comparten las vías.", ["La prevención empieza con decisiones cotidianas: respetar las señales, conducir con atención y mantener el vehículo en buenas condiciones.", "La legalidad implica cumplir las reglas; el respeto considera a los demás; la prevención anticipa peligros; la responsabilidad exige actuar con cuidado; la solidaridad protege a quien necesita ayuda.", "La seguridad no es tarea exclusiva de quien conduce: también participan peatones, ciclistas y motociclistas."], "En una zona escolar, bajar la velocidad y observar antes de avanzar es prevención y respeto."], ["legislacion", "resumen-05", "Ley de tránsito, permisos y documentación", "La ley de tránsito organiza cómo circulamos y qué responsabilidades asumimos.", ["El cuadro del manual presenta puntos, plazos de suspensión y consecuencias por infracciones. Revisá las cifras directamente en la página adjunta.", "Para circular se mencionan licencia vigente, marchamo al día, seguro y documento de identificación.", "El permiso de aprendizaje tiene requisitos específicos y exige acompañamiento; no equivale a una licencia plena.", "La inspección del vehículo incluye luces, llantas, frenos, cinturones, espejos y otros elementos de seguridad."], "Antes de salir, comprobás los documentos y revisás que el carro esté en buenas condiciones."], ["via", "resumen-06", "Vías urbanas, rurales y entorno", "La carretera cambia según su diseño y sus condiciones, por eso tu conducción también debe cambiar.", ["La vía urbana convive con peatones, comercios, cruces y múltiples accesos.", "La vía rural puede tener curvas, poca iluminación, animales y tramos con menor visibilidad.", "La calzada es por donde circulan vehículos; el carril es una división de esa calzada; el espaldón está a un lado.", "Clima, topografía, iluminación, vegetación, obras y estado del pavimento modifican el riesgo."], "En una curva mojada, disminuís la velocidad antes de entrar, no cuando ya estás girando."], ["vehiculo", "resumen-07", "Motor, embrague, llantas y seguridad pasiva", "Conocer las partes del vehículo ayuda a detectar problemas y prevenir accidentes.", ["El motor transforma energía en movimiento; los sistemas de lubricación y enfriamiento ayudan a que funcione adecuadamente.", "En vehículos manuales, el embrague permite acoplar y desacoplar el motor de la transmisión.", "Los frenos reducen la velocidad; la inspección y mantenimiento previenen fallas.", "Las llantas necesitan dibujo, presión y rotación adecuados. La presión incorrecta afecta el desgaste y la adherencia.", "Airbags, apoyacabezas y cinturón son sistemas de seguridad pasiva que reducen daños en un choque."], "Si notás desgaste desigual en una llanta, revisás presión, alineación y estado general antes de un viaje."], ["humano", "resumen-08", "Fatiga, alcohol, medicamentos y emociones", "Tu estado físico y mental influye directamente en tus decisiones al volante.", ["El manejo defensivo consiste en observar, anticipar y actuar con prudencia.", "La fatiga y la somnolencia disminuyen la concentración y el tiempo de reacción.", "El alcohol afecta juicio, coordinación y percepción; no debe combinarse con conducir.", "Algunos medicamentos provocan sueño o reducen reflejos: revisá las advertencias y consultá a un profesional.", "Las emociones intensas y las distracciones pueden hacerte perder información importante de la vía."], "Si estás muy cansada, detenete en un lugar seguro y descansá; abrir la ventana no sustituye dormir."], ["normas", "resumen-09", "Prioridades, señales, luces y velocidad", "Las normas hacen predecible el comportamiento de todos en la vía.", ["Los vehículos de emergencia con señales activas requieren facilitarles el paso de forma segura.", "En intersecciones sin señalización, el manual destaca la prioridad de quien viene por la derecha.", "Para adelantar se necesita visibilidad, espacio suficiente y señalización que lo permita.", "Las luces bajas, altas, direccionales y de emergencia tienen usos diferentes.", "La distancia de seguridad aumenta con la velocidad, lluvia o menor adherencia."], "Si una ambulancia se aproxima, buscás una manera segura de permitirle continuar sin realizar maniobras bruscas."], ["rotondas", "resumen-10", "Entradas, circulación y salidas de rotondas", "En una rotonda, la prioridad corresponde a quien ya está circulando dentro.", ["Al acercarte, reducís velocidad, observás y cedés el paso cuando corresponde.", "Elegí el carril según la salida que vas a utilizar y la señalización del lugar.", "Señalizá la salida con tiempo; no cambiés de carril de forma brusca.", "Prestá especial atención a peatones y ciclistas en los accesos.", "El esquema del manual distingue primera, segunda y última salida; estudiá el dibujo junto a esta explicación."], "Si necesitás salir por una salida posterior, prepará la maniobra con anticipación y respetá las marcas viales."], ["ambiente", "resumen-11", "Contaminación y conducción sostenible", "La forma de conducir también afecta la salud y el ambiente.", ["Los vehículos pueden generar contaminación del aire, ruido y residuos.", "El mantenimiento del motor y las llantas reduce emisiones y consumo innecesario.", "Acelerar y frenar bruscamente suele gastar más combustible.", "Compartir viajes, caminar o usar transporte público cuando sea posible reduce desplazamientos individuales."], "Si mantenés una velocidad estable y el vehículo revisado, ayudás a ahorrar combustible."], ["eficiente", "resumen-12", "Ahorro de combustible y frenado eficiente", "Conducir eficientemente es avanzar con suavidad, anticipación y seguridad.", ["Evitá aceleraciones innecesarias y frenazos tardíos.", "Anticipá semáforos y condiciones para reducir velocidad gradualmente.", "Mantené la presión correcta de las llantas y el vehículo al día.", "El manual relaciona velocidad elevada con mayor consumo de combustible.", "No sacrificás la seguridad por ahorrar: las normas siempre tienen prioridad."], "Si ves el semáforo rojo a lo lejos, soltás progresivamente el acelerador y frenás con suavidad."], ["motos", "resumen-13", "Protección y conducción de motocicletas", "Una motocicleta requiere especial atención porque sus ocupantes están más expuestos.", ["Usá casco apropiado, guantes, chaqueta, pantalón y calzado protector.", "La postura, la visibilidad y la distancia de seguridad son fundamentales.", "Lluvia, viento, noche y pavimento irregular exigen más precaución.", "El frenado y el adelantamiento deben hacerse con equilibrio y suficiente espacio.", "El mantenimiento incluye llantas, luces, frenos, cadena y otros componentes."], "Antes de cambiar de carril en carro, revisás espejos y punto ciego para detectar motocicletas."], ["senales", "resumen-14", "Familias de señales de tránsito", "Reconocer una señal permite decidir correctamente antes de llegar al peligro.", ["Reglamentarias: indican obligaciones y prohibiciones; ejemplos: PARE, CEDA, no estacionar y prohibido adelantar.", "Preventivas: advierten sobre curvas, intersecciones, zonas escolares y otros riesgos próximos.", "Informativas: ayudan a ubicar servicios o destinos, como hospital, aeropuerto y estacionamiento.", "Señales de servicio: muestran asistencia y equipamientos disponibles.", "Mirá la lámina original para aprender formas, colores y símbolos, no solo los nombres."], "Una señal amarilla de curva te avisa que debés adaptar la velocidad antes de llegar al giro."], ["proteccion", "anexo-02", "Cinturón, niñez y seguridad activa y pasiva", "Los sistemas de seguridad funcionan mejor cuando se usan correctamente.", ["La banda superior del cinturón pasa sobre el hombro y el pecho, nunca sobre el cuello.", "La banda inferior debe ajustarse sobre la pelvis, no sobre el abdomen.", "El material distingue sistemas de retención infantil según edad y tamaño; consultá las indicaciones exactas de la lámina.", "Seguridad activa ayuda a evitar el choque: ABS, luces, dirección, llantas y espejos.", "Seguridad pasiva disminuye las lesiones: cinturón, airbags, apoyacabezas y carrocería."], "Antes de encender el carro, comprobás que todas las personas estén sujetas correctamente."], ["legislacion", "anexo-03", "Clases de infracciones y sanciones", "El anexo agrupa infracciones en clases según gravedad.", ["Clase A reúne infracciones muy graves, como ciertas conductas relacionadas con alcohol y velocidad extrema.", "Clase B incluye conductas graves como no utilizar el dispositivo infantil adecuado y desobedecer señales importantes.", "Clase C menciona cinturón, motos y celular.", "Clase D contempla prioridad, estacionamiento y documentación.", "Las cantidades y puntos de la tabla son datos sensibles a cambios legales: verificá la norma oficial antes de memorizarlos como vigentes."], "Si una pregunta pide clasificar una infracción, identificás primero la conducta y después su clase en la tabla."], ["legislacion", "anexo-04", "Sistema de puntos de la licencia", "El sistema de puntos relaciona ciertas infracciones con consecuencias sobre la licencia.", ["El anexo presenta acumulación de puntos según categorías de infracción.", "También explica restricciones y suspensión al alcanzar determinados umbrales.", "Incluye opciones de sensibilización y reeducación vial para disminuir puntos bajo condiciones específicas.", "La reincidencia puede tener consecuencias adicionales.", "Los números del anexo deben contrastarse con el marco legal vigente antes de aplicarlos a un caso real."], "Si te preguntan por suspensión, no confundás los puntos acumulados con el monto económico de la multa."], ["rotondas", "anexo-05", "Rotonda: diez decisiones paso a paso", "La lámina divide el ingreso y salida de una rotonda en decisiones consecutivas.", ["Al aproximarte, reducís la velocidad y verificás si circulan vehículos dentro.", "Cedés el paso a quienes ya transitan por la rotonda.", "Seleccionás el carril apropiado antes de ingresar según la salida deseada.", "No adelantás dentro de la rotonda y evitás cambios de carril bruscos.", "Usás la direccional para comunicar la salida.", "Revisá los diez puntos numerados del dibujo original, especialmente la relación entre carril y salida."], "Si te equivocás de salida, evitá cruzarte abruptamente: continuá de manera segura y reorganizá la ruta."], ["adelantamiento", "anexo-06", "Cuándo está prohibido adelantar", "Adelantar solo es seguro cuando la vía, las señales y la visibilidad lo permiten.", ["No adelantés sobre línea amarilla continua ni en doble línea continua.", "El anexo muestra prohibiciones cerca de intersecciones, pasos peatonales, centros de salud y albergues.", "No adelantés cuando los semáforos o señales lo prohíban.", "Curvas, túneles, pasos a desnivel y otras zonas de visibilidad limitada requieren especial precaución.", "Antes de adelantar, verificá que podás completar la maniobra sin obligar a otros a frenar."], "Aunque el carro de adelante vaya lento, una línea continua sigue prohibiendo la maniobra."], ["vehiculo", "anexo-07", "Frenos de mano, disco, tambor y ABS", "Cada sistema de frenos cumple una función en la seguridad.", ["El freno de estacionamiento ayuda a mantener inmóvil el vehículo al detenerlo.", "Los frenos de disco emplean pastillas y discos; los de tambor usan componentes dentro de un tambor.", "El ABS ayuda a evitar el bloqueo de ruedas en una frenada fuerte, facilitando mantener el control de dirección.", "La distancia de frenado cambia según velocidad, llantas, pavimento y estado del vehículo.", "El mantenimiento y la revisión periódica son indispensables."], "En una frenada de emergencia con ABS, mantenés presión firme y dirigís el vehículo hacia un espacio seguro."], ["viaje", "anexo-08", "Preparación del viaje y seguridad de pasajeros", "Un viaje seguro se planifica antes de poner el vehículo en movimiento.", ["Revisá el estado mecánico y los documentos del carro.", "Evaluá si estás descansada, alerta y en condiciones de conducir.", "Planificá ruta, clima, paradas y descansos.", "Todos los pasajeros necesitan cinturón y los niños, el dispositivo adecuado.", "Asegurá equipaje, objetos y mascotas para evitar desplazamientos peligrosos.", "Durante trayectos largos, hacé pausas en lugares seguros."], "Antes de ir a la playa, revisás llantas, documentos, ruta y descansos."], ["viaje", "anexo-09", "Distancia segura y regla de tres segundos", "La distancia es el espacio que te permite reaccionar y detenerte.", ["El anexo propone contar tres segundos usando un punto fijo como referencia.", "A mayor velocidad, necesitás mayor distancia.", "Con lluvia o baja adherencia, aumentá el espacio.", "La fatiga y la somnolencia afectan tu reacción.", "El mantenimiento y las condiciones de la vía también influyen en la distancia necesaria."], "Cuando el vehículo de adelante pasa un poste, empezás a contar; si llegás antes de tres segundos, te alejás."], ["viaje", "anexo-10", "Obligaciones del conductor", "Conducir es un privilegio que implica responsabilidades concretas.", ["Respetá todas las señales e indicaciones de las autoridades.", "Asegurá las condiciones mecánicas y documentales del vehículo.", "Cuidá a los demás usuarios de la vía.", "Conducí en condiciones físicas, mentales y emocionales adecuadas.", "No utilicés el celular mientras manejás y mantené distancia de seguridad."], "Si recibís un mensaje mientras conducís, esperás a detenerte de manera segura antes de responder."], ["licencias", "anexo-11", "Modalidades de licencias y requisitos", "La clase de licencia depende del tipo de vehículo y de sus condiciones.", ["El anexo distingue licencias B-1, B-2, B-3 y B-4 para distintas categorías de vehículos.", "También presenta clases A, C, D y E para otras modalidades.", "Cada categoría tiene requisitos y condiciones que debés revisar en la lámina.", "No asumás que una licencia permite manejar cualquier vehículo."], "Antes de conducir un vehículo de carga, comprobás que tu categoría de licencia sea la correspondiente."], ["licencias", "anexo-12", "Conductora novata, profesional y común", "El anexo diferencia perfiles de conductores.", ["Conductor novato: persona que obtiene licencia por primera vez y tiene poca antigüedad.", "Conductor profesional: conduce como actividad principal, por ejemplo para trasladar personas o mercancías.", "Conductor común o no tipificado: renueva su licencia con experiencia y sin actividad profesional de conducción.", "La lámina presenta categorías de licencia asociadas a cada perfil."], "Una persona que maneja su carro personal no es automáticamente conductora profesional."], ["via", "anexo-13", "Carreteras, calles y caminos en Costa Rica", "No todas las vías cumplen la misma función.", ["Las carreteras se dividen en primarias, secundarias y terciarias.", "Las calles locales facilitan la circulación dentro de zonas urbanas.", "Los caminos vecinales conectan propiedades y comunidades rurales.", "Los caminos no clasificados pueden tener superficies y condiciones más variables.", "Adaptá la velocidad y la atención al tipo de vía."], "Una carretera primaria conecta regiones importantes; una calle local suele servir a un barrio."], ["viaje", "anexo-14", "Factores de riesgo de accidentes y lesiones", "El riesgo depende de la exposición, la posibilidad de choque y la gravedad de las consecuencias.", ["La exposición al riesgo aumenta con factores como tráfico, distancia y condiciones de circulación.", "La probabilidad de accidente depende de estado de la vía, vehículo, conductor y cumplimiento de normas.", "La gravedad de lesiones puede aumentar con velocidad y ausencia de dispositivos de protección.", "La atención después de un accidente también influye en sus consecuencias."], "De noche, con lluvia y cansancio, se acumulan riesgos: lo prudente es reducir la exposición y descansar."]];
for(const [id,page,title,simple,detail,example] of PAGE_GUIDES){const m=COURSE.find(x=>x.id===id);if(!m)continue;m.lessons.push({title:"📖 "+title,simple,detail,example,remember:"Consultá la lámina original: "+page.replace("-"," · página ")+". Estudiá el texto y la imagen juntos."});if(!m.pages.includes(page))m.pages.push(page);}
